     }
+
+    #[test]
+    fn load_config_file_rejects_unknown_fields() {
+        let temp = TempDir::new().unwrap();
+        let config_path = temp.path().join("config.yml");
+        fs::write(&config_path, "app_name: TestApp\nunknown_field: oops\n").unwrap();
+
+        let result = load_config_file(&config_path);
+        assert!(
+            matches!(result, Err(BivvyError::ConfigParseError { .. })),
+            "unknown field in config file must produce ConfigParseError"
+        );
+    }
+
+    #[test]
+    fn load_merged_config_rejects_unknown_fields() {
+        let temp = TempDir::new().unwrap();
+        let bivvy_dir = temp.path().join(".bivvy");
+        fs::create_dir_all(&bivvy_dir).unwrap();
+        fs::write(
+            bivvy_dir.join("config.yml"),
+            "app_name: TestApp\nbogus_key: whoops\n",
+        )
+        .unwrap();
+
+        let result = load_merged_config(temp.path());
+        assert!(
+            result.is_err(),
+            "merged config with unknown field must fail"
+        );
+    }
 }
